B.asF=s(["\u0646\u062d\u062a\u0641\u0638 \u0628\u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0637\u0648\u0627\u0644 \u0648\u062c\u0648\u062f \u062d\u0633\u0627\u0628\u0643. \u0639\u0646\u062f \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0646\u062d\u0630\u0641 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u062e\u0644\u0627\u0644 30 \u064a\u0648\u0645\u0627\u064b\u060c \u0625\u0644\u0627 \u0645\u0627 \u064a\u0644\u0632\u0645\u0646\u0627 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0628\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0647 \u0623\u0648 \u0645\u0627 \u064a\u062e\u0635 \u0633\u062c\u0644\u0627\u062a \u0645\u0627\u0644\u064a\u0629 \u0623\u0648 \u0642\u0631\u0627\u0631\u0627\u062a \u0639\u0645\u0627\u0631\u0629 \u0634\u0627\u0631\u0643 \u0641\u064a\u0647\u0627 \u063a\u064a\u0631\u0643."],t.s)
B.al7=new A.h0("\u0645\u062f\u0629 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638",B.asF)
B.ay5=s(["\u064a\u062d\u0642 \u0644\u0643 \u0623\u0646 \u062a\u0639\u0631\u0641 \u0645\u0627 \u0646\u062d\u062a\u0641\u0638 \u0628\u0647 \u0639\u0646\u0643\u060c \u0648\u0623\u0646 \u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0646\u0633\u062e\u0629 \u0645\u0646\u0647\u060c \u0648\u0623\u0646 \u062a\u0635\u062d\u0651\u062d\u0647\u060c \u0648\u0623\u0646 \u062a\u0637\u0644\u0628 \u062d\u0630\u0641\u0647 \u0623\u0648 \u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0623\u0646 \u062a\u0633\u062d\u0628 \u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0648\u0642\u0639 \u0623\u0648 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0641\u064a \u0623\u064a \u0648\u0642\u062a \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u062c\u0647\u0627\u0632\u0643.","\u0648\u0625\u0630\u0627 \u0645\u0646\u062d\u0643 \u0642\u0627\u0646\u0648\u0646 \u0628\u0644\u062f\u0643 \u062d\u0642\u0648\u0642\u0627\u064b \u0625\u0636\u0627\u0641\u064a\u0629\u060c \u0645\u062b\u0644 \u0627\u0644\u0627\u0639\u062a\u0631\u0627\u0636 \u0639\u0644\u0649 \u0645\u0639\u0627\u0644\u062c\u0629 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0623\u0648 \u062a\u0642\u062f\u064a\u0645 \u0634\u0643\u0648\u0649 \u0644\u0644\u062c\u0647\u0629 \u0627\u0644\u0645\u062e\u062a\u0635\u0629 \u0628\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0641\u064a \u0628\u0644\u062f\u0643\u060c \u0641\u0646\u062d\u0646 \u0646\u062d\u062a\u0631\u0645\u0647\u0627.",'\u0644\u062a\u0646\u0641\u064a\u0630 \u0623\u064a \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0631\u0627\u0633\u0644\u0646\u0627 \u0645\u0646 "\u0627\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0648\u0627\u0644\u062f\u0639\u0645" \u0623\u0648 \u0639\u0644\u0649 \u0627\u0644\u0628\u0631\u064a\u062f mogtama3y.eg@gmail.com\u060c \u0648\u0633\u0646\u0631\u062f \u062e\u0644\u0627\u0644 30 \u064a\u0648\u0645\u0627\u064b.'],t.s)
